package com.mukasanches.zapptv.model

data class ProgramInfo(
    val channelId: String,
    val title: String,
    val subtitle: String? = null,
    val description: String? = null,
    val startMillis: Long? = null,
    val endMillis: Long? = null
) {
    fun progress(now: Long = System.currentTimeMillis()): Float {
        val start = startMillis ?: return 0f
        val end = endMillis ?: return 0f
        if (end <= start) return 0f
        return ((now - start).toFloat() / (end - start).toFloat()).coerceIn(0f, 1f)
    }
}

package com.mukasanches.zapptv.nativebridge

import android.content.Context
import android.media.tv.TvInputInfo
import android.media.tv.TvInputManager
import android.os.Build
import com.mukasanches.zapptv.model.TvCapabilityProfile
import com.mukasanches.zapptv.model.TvInputSummary

open class GenericTvAdapter : TvPlatformAdapter {
    override fun detect(context: Context): TvCapabilityProfile {
        val manager = context.getSystemService(TvInputManager::class.java)
        val inputList: List<TvInputInfo> = manager?.tvInputList ?: emptyList()

        val inputs = inputList.map { input: TvInputInfo ->
            val packageName = runCatching {
                input.serviceInfo.packageName
            }.getOrNull()

            TvInputSummary(
                id = input.id,
                label = runCatching { input.loadLabel(context).toString() }
                    .getOrDefault("Entrada de TV"),
                type = input.type,
                state = runCatching { manager?.getInputState(input.id) }
                    .getOrNull() ?: TvInputManager.INPUT_STATE_DISCONNECTED,
                packageName = packageName,
                passthrough = input.isPassthroughInput
            )
        }

        val tunerInputs = inputs.filter { it.type == TvInputInfo.TYPE_TUNER }
        return TvCapabilityProfile(
            manufacturer = Build.MANUFACTURER.orEmpty(),
            model = Build.MODEL.orEmpty(),
            androidApi = Build.VERSION.SDK_INT,
            fingerprint = Build.FINGERPRINT.orEmpty(),
            isTcl = Build.MANUFACTURER.equals("TCL", ignoreCase = true),
            tvInputs = inputs,
            tunerCount = tunerInputs.size,
            hdmiCount = inputs.count { it.type == TvInputInfo.TYPE_HDMI },
            nativeTvPackage = tunerInputs.firstNotNullOfOrNull { it.packageName }
        )
    }
}

package com.mukasanches.zapptv.nativebridge

import android.content.Context
import android.content.Intent
import android.media.tv.TvContract
import android.net.Uri
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.TvCapabilityProfile
import com.mukasanches.zapptv.model.TvInputSummary

class NativeTvBridge(private val context: Context) {

    fun launchNativeTv(profile: TvCapabilityProfile): Boolean {
        val packageName = profile.nativeTvPackage
        if (!packageName.isNullOrBlank()) {
            val packageManager = context.packageManager
            val launch = packageManager.getLeanbackLaunchIntentForPackage(packageName)
                ?: packageManager.getLaunchIntentForPackage(packageName)
            if (launch != null && start(launch)) return true
        }

        return start(Intent(Intent.ACTION_VIEW, TvContract.Channels.CONTENT_URI))
    }

    fun launchChannel(channel: Channel): Boolean {
        val uri = channel.uri?.let(Uri::parse) ?: return false
        return start(Intent(Intent.ACTION_VIEW, uri))
    }

    fun launchInput(input: TvInputSummary): Boolean {
        if (!input.passthrough) return false
        val uri = TvContract.buildChannelUriForPassthroughInput(input.id)
        return start(Intent(Intent.ACTION_VIEW, uri))
    }

    fun launchWeb(url: String): Boolean =
        start(Intent(Intent.ACTION_VIEW, Uri.parse(url)).addCategory(Intent.CATEGORY_BROWSABLE))

    private fun start(intent: Intent): Boolean {
        return runCatching {
            if (context !is android.app.Activity) {
                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
            context.startActivity(intent)
            true
        }.getOrDefault(false)
    }
}

