@Composable
fun PlayerSurface(channel: Channel?) {
    when (channel?.source) {
        ChannelSource.NATIVE_TUNER -> NativeTvSurface(channel)
        ChannelSource.HLS,
        ChannelSource.IPTV -> StreamSurface(channel)
        else -> IdleSurface()
    }
}

@Composable
private fun NativeTvSurface(channel: Channel) {
    val inputId = channel.nativeInputId
    val channelUri = channel.uri
    if (inputId == null || channelUri == null) {
        IdleSurface()
        return
    }

    key(channel.id) {
        AndroidView(
            factory = { context ->
                TvView(context).apply {
                    setBackgroundColor(android.graphics.Color.BLACK)
                    tune(inputId, Uri.parse(channelUri))
                }
            },
            modifier = Modifier.fillMaxSize()
        )
    }
}

@Composable
private fun StreamSurface(channel: Channel) {
    val context = LocalContext.current
    val uri = channel.uri
    if (uri.isNullOrBlank()) {
        IdleSurface()
        return
    }

    val player = remember {
        val loadControl = DefaultLoadControl.Builder()
            .setBufferDurationsMs(
                2_500,
                15_000,
                500,
                1_000
            )
            .build()

        ExoPlayer.Builder(context)
            .setLoadControl(loadControl)
            .build()
            .apply {
                playWhenReady = true
                setHandleAudioBecomingNoisy(true)
            }
    }

    LaunchedEffect(uri) {
        val lower = uri.lowercase()
        val item = MediaItem.Builder()
            .setUri(uri)
            .apply {
                when {
                    ".m3u8" in lower -> setMimeType(MimeTypes.APPLICATION_M3U8)
                    ".mpd" in lower -> setMimeType(MimeTypes.APPLICATION_MPD)
                }
            }
            .build()

        player.setMediaItem(item)
        player.prepare()
        player.play()
    }

    DisposableEffect(player) {
        onDispose { player.release() }
    }

    AndroidView(
        factory = {
            PlayerView(it).apply {
                useController = false
                resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                this.player = player
            }
        },
        update = {
            it.player = player
        },
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
    )
}

@Composable
private fun IdleSurface() {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.radialGradient(
                    colors = listOf(Color(0xFF18202B), ZappColors.Background),
                    radius = 1500f
                )
            )
    )
}

