@Composable
fun ZappTvApp(
    registerKeyHandler: (((KeyEvent) -> Boolean)?) -> Unit
) {
    val context = LocalContext.current
    val controller = remember { ZappController(context) }

    DisposableEffect(controller) {
        controller.start()
        registerKeyHandler(controller::handleKey)
        onDispose {
            registerKeyHandler(null)
            controller.close()
        }
    }

    ZappTheme {
        val state = controller.state
        if (state.loading) {
            BootScreen()
            return@ZappTheme
        }

        Box(Modifier.fillMaxSize().background(ZappColors.Background)) {
            PlayerSurface(state.currentChannel)

            if (state.screen == AppScreen.WATCH) {
                if (controller.overlayVisible) {
                    WatchOverlay(
                        channel = state.currentChannel,
                        program = state.currentProgram,
                        profileLabel = state.profile?.model.orEmpty(),
                        message = state.message
                    )
                }
            } else {
                ModalBackground()
                when (state.screen) {
                    AppScreen.CHANNELS -> ChannelBrowser(
                        title = "Canais",
                        channels = state.channels,
                        programs = state.programs,
                        favorites = state.favorites,
                        selectedId = state.currentChannel?.id,
                        onSelect = controller::select,
                        onFavorite = controller::toggleFavorite,
                        onNavigate = controller::open
                    )
                    AppScreen.GUIDE -> ChannelBrowser(
                        title = "Agora na TV",
                        channels = state.channels,
                        programs = state.programs,
                        favorites = state.favorites,
                        selectedId = state.currentChannel?.id,
                        onSelect = controller::select,
                        onFavorite = controller::toggleFavorite,
                        onNavigate = controller::open
                    )
                    AppScreen.IPTV -> ChannelBrowser(
                        title = "IPTV Brasil",
                        channels = state.channels.filter {
                            it.source == ChannelSource.IPTV || it.source == ChannelSource.HLS
                        },
                        programs = state.programs,
                        favorites = state.favorites,
                        selectedId = state.currentChannel?.id,
                        onSelect = controller::select,
                        onFavorite = controller::toggleFavorite,
                        onNavigate = controller::open
                    )
                    AppScreen.FAVORITES -> ChannelBrowser(
                        title = "Favoritos",
                        channels = state.channels.filter { it.id in state.favorites },
                        programs = state.programs,
                        favorites = state.favorites,
                        selectedId = state.currentChannel?.id,
                        onSelect = controller::select,
                        onFavorite = controller::toggleFavorite,
                        onNavigate = controller::open
                    )
                    AppScreen.INPUTS -> InputsScreen(
                        inputs = state.profile?.tvInputs.orEmpty(),
                        onInput = controller::launchInput,
                        onNavigate = controller::open
                    )
                    AppScreen.SEARCH -> SearchScreen(
                        channels = state.channels,
                        programs = state.programs,
                        onSelect = controller::select,
                        onNavigate = controller::open
                    )
                    AppScreen.DIAGNOSTICS -> DiagnosticsScreen(
                        controller = controller,
                        onNavigate = controller::open
                    )
                    AppScreen.WATCH -> Unit
                }
            }
        }
    }
}

