@Composable
private fun WatchOverlay(
    channel: Channel?,
    program: ProgramInfo?,
    profileLabel: String,
    message: String?
) {
    val progress = program?.progress() ?: 0f
    Box(
        Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    0f to Color.Transparent,
                    0.56f to Color.Transparent,
                    1f to Color(0xF207090D)
                )
            )
    ) {
        Text(
            text = "ZappTV",
            modifier = Modifier
                .align(Alignment.TopStart)
                .padding(start = 58.dp, top = 42.dp),
            color = Color.White.copy(alpha = 0.86f),
            fontSize = 21.sp,
            fontWeight = FontWeight.SemiBold
        )

        Column(
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = 58.dp, end = 58.dp, bottom = 44.dp)
                .fillMaxWidth()
        ) {
            Text(
                text = listOfNotNull(
                    channel?.number?.takeIf { it.isNotBlank() },
                    channel?.name
                ).joinToString("  "),
                color = ZappColors.PrimaryText,
                fontSize = 34.sp,
                fontWeight = FontWeight.Bold
            )
            Spacer(Modifier.height(8.dp))
            Text(
                text = program?.title ?: when {
                    channel == null -> "Nenhum canal disponível"
                    else -> "Ao vivo"
                },
                color = ZappColors.PrimaryText,
                fontSize = 25.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )

            val details = listOfNotNull(program?.subtitle, program?.description)
                .joinToString(" • ")
                .takeIf { it.isNotBlank() }
            if (details != null) {
                Spacer(Modifier.height(7.dp))
                Text(
                    text = details,
                    color = ZappColors.SecondaryText,
                    fontSize = 15.sp,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
            }

            if (program?.startMillis != null && program.endMillis != null) {
                Spacer(Modifier.height(14.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        formatTime(program.startMillis),
                        color = ZappColors.SecondaryText,
                        fontSize = 15.sp
                    )
                    Spacer(Modifier.width(14.dp))
                    Box(
                        Modifier
                            .weight(1f)
                            .height(4.dp)
                            .clip(RoundedCornerShape(2.dp))
                            .background(Color.White.copy(alpha = 0.22f))
                    ) {
                        Box(
                            Modifier
                                .fillMaxWidth(progress)
                                .fillMaxHeight()
                                .background(ZappColors.Progress)
                        )
                    }
                    Spacer(Modifier.width(14.dp))
                    Text(
                        formatTime(program.endMillis),
                        color = ZappColors.SecondaryText,
                        fontSize = 15.sp
                    )
                }
            }

            if (!message.isNullOrBlank()) {
                Spacer(Modifier.height(12.dp))
                Text(
                    text = message,
                    color = ZappColors.PrimaryText,
                    fontSize = 17.sp,
                    fontWeight = FontWeight.SemiBold
                )
            }

            Spacer(Modifier.height(16.dp))
            Text(
                text = "↑ Guia   ↓ Lista   ←/→ ou CH± Trocar   Números Ir ao canal   Vermelho Atualizar   •   " +
                    profileLabel,
                color = ZappColors.SecondaryText,
                fontSize = 14.sp
            )
        }
    }
}

@Composable
private fun ChannelBrowser(
    title: String,
    channels: List<Channel>,
    programs: Map<String, ProgramInfo>,
    favorites: Set<String>,
    selectedId: String?,
    onSelect: (Channel) -> Unit,
    onFavorite: (Channel) -> Unit,
    onNavigate: (AppScreen) -> Unit
) {
    Column(
        Modifier
            .fillMaxSize()
            .padding(horizontal = 62.dp, vertical = 42.dp)
    ) {
        Header(title, onNavigate)
        Spacer(Modifier.height(26.dp))

        if (channels.isEmpty()) {
            Text(
                "Nenhum canal nesta seção.",
                color = ZappColors.SecondaryText,
                fontSize = 22.sp
            )
            return
        }

        LazyColumn(
            verticalArrangement = Arrangement.spacedBy(8.dp),
            modifier = Modifier.fillMaxSize()
        ) {
            items(channels, key = { it.id }) { channel ->
                ChannelRow(
                    channel = channel,
                    program = programs[channel.id],
                    favorite = channel.id in favorites,
                    autoFocus = channel.id == selectedId,
                    onClick = { onSelect(channel) },
                    onFavorite = { onFavorite(channel) }
                )
            }
        }
    }
}

@Composable
private fun ChannelRow(
    channel: Channel,
    program: ProgramInfo?,
    favorite: Boolean,
    autoFocus: Boolean,
    onClick: () -> Unit,
    onFavorite: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }
    val requester = remember { FocusRequester() }
    val scale by animateFloatAsState(if (focused) 1.018f else 1f)

    LaunchedEffect(autoFocus) {
        if (autoFocus) {
            delay(90)
            runCatching { requester.requestFocus() }
        }
    }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(82.dp)
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
            .clip(RoundedCornerShape(16.dp))
            .background(if (focused) ZappColors.Focus else ZappColors.Surface)
            .focusRequester(requester)
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onClick)
            .focusable()
            .padding(horizontal = 22.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            channel.number.ifBlank { "•" },
            modifier = Modifier.width(92.dp),
            color = if (focused) ZappColors.FocusText else ZappColors.SecondaryText,
            fontSize = 20.sp,
            fontWeight = FontWeight.SemiBold
        )
        Column(Modifier.weight(1f)) {
            Text(
                channel.name,
                color = if (focused) ZappColors.FocusText else ZappColors.PrimaryText,
                fontSize = 22.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1
            )
            Text(
                program?.title ?: channel.category,
                color = if (focused) ZappColors.FocusText.copy(alpha = 0.72f)
                else ZappColors.SecondaryText,
                fontSize = 15.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
        FocusChip(
            text = if (favorite) "★" else "☆",
            selected = favorite,
            onClick = onFavorite
        )
    }
}

