            color = if (focused) ZappColors.FocusText else ZappColors.PrimaryText,
            fontSize = 21.sp,
            fontWeight = FontWeight.SemiBold
        )
        Text(
            status,
            color = if (focused) ZappColors.FocusText.copy(alpha = 0.7f)
            else ZappColors.SecondaryText,
            fontSize = 15.sp
        )
    }
}

@Composable
private fun SearchScreen(
    channels: List<Channel>,
    programs: Map<String, ProgramInfo>,
    onSelect: (Channel) -> Unit,
    onNavigate: (AppScreen) -> Unit
) {
    var query by remember { mutableStateOf("") }
    val requester = remember { FocusRequester() }

    LaunchedEffect(Unit) {
        delay(120)
        runCatching { requester.requestFocus() }
    }

    val normalized = ChannelResolver.normalize(query)
    val filtered = if (normalized.isBlank()) {
        channels
    } else {
        channels.filter { channel ->
            ChannelResolver.normalize(channel.name).contains(normalized) ||
                ChannelResolver.normalize(programs[channel.id]?.title.orEmpty()).contains(normalized)
        }
    }

    Column(
        Modifier
            .fillMaxSize()
            .padding(horizontal = 62.dp, vertical = 42.dp)
    ) {
        Header("Buscar", onNavigate)
        Spacer(Modifier.height(22.dp))
        OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            singleLine = true,
            label = { Text("Canal ou programa") },
            modifier = Modifier
                .fillMaxWidth(0.62f)
                .focusRequester(requester)
        )
        Spacer(Modifier.height(22.dp))
        LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            items(filtered, key = { it.id }) { channel ->
                ChannelRow(
                    channel = channel,
                    program = programs[channel.id],
                    favorite = false,
                    autoFocus = false,
                    onClick = { onSelect(channel) },
                    onFavorite = {}
                )
            }
        }
    }
}

@Composable
private fun DiagnosticsScreen(
    controller: ZappController,
    onNavigate: (AppScreen) -> Unit
) {
    val state = controller.state
    val profile = state.profile

    Column(
        Modifier
            .fillMaxSize()
            .padding(horizontal = 62.dp, vertical = 42.dp)
    ) {
        Header("Diagnóstico", onNavigate)
        Spacer(Modifier.height(28.dp))

        val rows = listOf(
            "Fabricante" to profile?.manufacturer.orEmpty(),
            "Modelo" to profile?.model.orEmpty(),
            "Android API" to (profile?.androidApi?.toString() ?: "—"),
            "Integração TCL" to if (profile?.isTcl == true) "Detectada" else "Genérica",
            "Tuners" to (profile?.tunerCount?.toString() ?: "0"),
            "HDMI" to (profile?.hdmiCount?.toString() ?: "0"),
            "Canais disponíveis" to state.channels.size.toString(),
            "Canais IPTV" to state.iptvChannelCount.toString(),
            "Programas com EPG agora" to state.epgProgramCount.toString(),
            "IPTV / EPG" to state.onlineStatus,
            "Última sincronização" to state.lastOnlineRefreshMillis
                .takeIf { it > 0L }
                ?.let(::formatDateTime)
                .orEmpty(),
            "Banco nativo de canais" to if (state.nativeDatabaseReadable) "Acessível" else "Protegido / fallback",
            "App TV nativo" to (profile?.nativeTvPackage ?: "Descoberta por intent")
        )

        rows.forEach { (label, value) ->
            Row(
                Modifier
                    .fillMaxWidth()
                    .padding(vertical = 9.dp)
                    .animateContentSize()
            ) {
                Text(
                    label,
                    modifier = Modifier.width(280.dp),
                    color = ZappColors.SecondaryText,
                    fontSize = 17.sp
                )
                Text(
                    value.ifBlank { "—" },
                    color = ZappColors.PrimaryText,
                    fontSize = 17.sp,
                    fontWeight = FontWeight.Medium
                )
            }
        }
    }
}

private fun formatTime(value: Long): String =
    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date(value))

private fun formatDateTime(value: Long): String =
    SimpleDateFormat("dd/MM HH:mm", Locale("pt", "BR")).format(Date(value))
